Gap = 2:
  dp[0][2] = 3 (last=1)
  dp[1][3] = 15 (last=2)
  dp[2][4] = 40 (last=3)
  dp[3][5] = 40 (last=4)
Gap = 3:
  dp[0][3] = 30 (last=2)
